            "hat": "event_whenflagclicked",
            "hatId": "hat_player_init_1",
            "blocks": [
                {"opcode": "motion_gotoxy", "inputs": {"X": 0, "Y": 0}},
                {"opcode": "looks_show"},
                # Set all game variables using the official variable names from project_metadata
                {"opcode": "data_setvariableto", "inputs": {"VALUE": 0}, "fields": {"VARIABLE": "分数"}},
                {"opcode": "data_setvariableto", "inputs": {"VALUE": 5}, "fields": {"VARIABLE": "生命"}},
