        {
            "hat": "event_whenbroadcastreceived",
            "hatId": "hat_stage_game_start_1",
            "blocks": [
                {"opcode": "control_repeat_until",
                 "inputs": {"CONDITION": {
                    "opcode": "operator_equals",
                    "inputs": {"OPERAND1": {"opcode": "data_variable", "inputs": {}, "fields": {"VARIABLE": "状态"}},
                            "OPERAND2": "ready"}
