                "SUBSTACK": [
                    {"opcode": "data_setvariableto", "inputs": {"VALUE": "playing"}, "fields": {"VARIABLE": "状态"}}
                ]
                }
            ]
        },
        # Apple spawning - constant rate
        {
            "hat": "event_whenbroadcastreceived",
            "hatId": "hat_apple_spawner",
            "blocks": [
                {"opcode": "event_broadcast", "inputs": {"BROADCAST_INPUT": "生成苹果"}}
