                        "inputs": {"CONDITION": {"opcode": "operator_gt", "inputs": {"OPERAND1": {"opcode": "data_variable", "inputs": {}, "fields": {"VARIABLE": "分数"}},
                                                                                    "OPERAND2": 10}},
                                "SUBSTACK": [
