def load_json_file(path):
    """Load a JSON file and return its contents."""
    try:
        with open(path, 'r', encoding='utf-8') as f:
            return json.load(f)
    except Exception as e:
        print(f"  Error loading {path}: {e}")
        return None

def validate_structure(dsl):
    """Validate top-level structure."""
    issues = []
    # Check top-level has exactly one key 'scripts'
    if list(dsl.keys()) != ['scripts']:
        issues.append("Top-level structure incorrect. Expected ['scripts'], got " + str(list(dsl.keys())))
    # Check scripts is an array
    if not isinstance(dsl.get('scripts'), list):
        issues.append("scripts is not an array")
    return issues

def validate_scripts(dsl):
    """Validate all script objects."""
    issues = []
    hat_ids = []

    for i, script in enumerate(dsl.get('scripts', [])):
        # Check required fields
        for field in ['hat', 'hatId', 'blocks']:
            if field not in script:
                issues.append(f"Script {i}: missing required field '{field}'")

        # Check hatId is unique
        hat_id = script.get('hatId')
        if hat_id in hat_ids:
            issues.append(f"Script {i}: duplicate hatId '{hat_id}'")
        hat_ids.append(hat_id)

    return issues

def validate_opcodes(dsl):
    """Validate all block opcodes."""
    issues = []
    for script in dsl.get('scripts', []):
        for block in script.get('blocks', []):
            opcode = block.get('opcode')
            if opcode not in VALID_OPCODES:
                issues.append(f"Invalid opcode '{opcode}' in script {script.get('hatId')}, hat {script.get('hat')}")
    return issues

def validate_block_inputs_fields(dsl):
    """Validate that all blocks have required inputs and fields."""
    issues = []
    for script in dsl.get('scripts', []):
        for block in script.get('blocks', []):
            opcode = block.get('opcode')
            if opcode in OPCODE_REQUIREMENTS:
                req = OPCODE_REQUIREMENTS[opcode]
                # Check inputs
                for inp in req['inputs']:
                    if inp not in block.get('inputs', {}):
                        issues.append(f"Block '{opcode}' in script '{script.get('hatId')}' missing required input '{inp}'")
                # Check fields
                for fld in req.get('fields', []):
                    if fld not in block.get('fields', {}):
                        issues.append(f"Block '{opcode}' in script '{script.get('hatId')}' missing required field '{fld}'")
    return issues

def validate_special_blocks(dsl):
    """Validate special block requirements."""
    issues = []
    errors = []
    warnings = []

    for script in dsl.get('scripts', []):
        for block in script.get('blocks', []):
            opcode = block.get('opcode')

            # control_forever must have non-empty SUBSTACK
            if opcode == 'control_forever':
                substack = block.get('inputs', {}).get('SUBSTACK')
                if substack is None or (isinstance(substack, list) and len(substack) == 0):
                    errors.append(f"control_forever in '{script.get('hatId')}' has empty or missing SUBSTACK")

            # control_if CONDITION must be boolean reporter
            if opcode == 'control_if':
                cond = block.get('inputs', {}).get('CONDITION')
                if cond is None:
                    errors.append(f"control_if in '{script.get('hatId')}' missing CONDITION")
                elif cond.get('opcode') not in BOOLEAN_REPORTERS:
                    errors.append(f"control_if CONDITION in '{script.get('hatId')}' is not a boolean reporter: {cond.get('opcode')}")

            # control_repeat_until must have both CONDITION and non-empty SUBSTACK
            if opcode == 'control_repeat_until':
                cond = block.get('inputs', {}).get('CONDITION')
                substack = block.get('inputs', {}).get('SUBSTACK')
                if cond is None:
                    errors.append(f"control_repeat_until in '{script.get('hatId')}' missing CONDITION")
                if substack is None or (isinstance(substack, list) and len(substack) == 0):
                    errors.append(f"control_repeat_until in '{script.get('hatId')}' has empty or missing SUBSTACK")

            # control_create_clone_of CLONE_OPTION must be self or sprite name
            if opcode == 'control_create_clone_of':
                clone_option = block.get('inputs', {}).get('CLONE_OPTION')
                if clone_option not in ['_myself_', '_self_']:
                    errors.append(f"control_create_clone_of in '{script.get('hatId')}' has invalid CLONE_OPTION: {clone_option}")

            # control_delete_this_clone should have no inputs
            if opcode == 'control_delete_this_clone':
                inputs = block.get('inputs')
                if inputs is not None and len(inputs) > 0:
                    warnings.append(f"control_delete_this_clone in '{script.get('hatId')}' has unexpected inputs")

            # motion_gotoxy needs X and Y
            if opcode == 'motion_gotoxy':
                inputs = block.get('inputs', {})
                if 'X' not in inputs or 'Y' not in inputs:
                    errors.append(f"motion_gotoxy in '{script.get('hatId')}' missing X or Y")

            # event_broadcast needs BROADCAST_INPUT
            if opcode == 'event_broadcast':
                inputs = block.get('inputs', {})
                if 'BROADCAST_INPUT' not in inputs:
                    errors.append(f"event_broadcast in '{script.get('hatId')}' missing BROADCAST_INPUT")

            # event_broadcastandwait needs BROADCAST_INPUT
            if opcode == 'event_broadcastandwait':
                inputs = block.get('inputs', {})
                if 'BROADCAST_INPUT' not in inputs:
                    errors.append(f"event_broadcastandwait in '{script.get('hatId')}' missing BROADCAST_INPUT")

            # data_setvariableto needs VARIABLE field
            if opcode == 'data_setvariableto':
                fields = block.get('fields', {})
                if 'VARIABLE' not in fields:
                    errors.append(f"data_setvariableto in '{script.get('hatId')}' missing VARIABLE field")

            # data_changevariableby needs VARIABLE field
            if opcode == 'data_changevariableby':
                fields = block.get('fields', {})
                if 'VARIABLE' not in fields:
                    errors.append(f"data_changevariableby in '{script.get('hatId')}' missing VARIABLE field")

            # data_variable needs VARIABLE field
            if opcode == 'data_variable':
                fields = block.get('fields', {})
                if 'VARIABLE' not in fields:
                    errors.append(f"data_variable in '{script.get('hatId')}' missing VARIABLE field")

            # sensing_touchingobject TOUCHINGOBJECTMENU must be valid
            if opcode == 'sensing_touchingobject':
                touching = block.get('inputs', {}).get('TOUCHINGOBJECTMENU', '')
                valid_touch = ['_edge_', '_mouse_', '_self_', '_mouse_'] + [s for s in dsl.get('sprites', []) if s not in ['_stage_', '_me_']]
                if touching not in valid_touch:
                    errors.append(f"sensing_touchingobject in '{script.get('hatId')}' has invalid TOUCHINGOBJECTMENU: {touching}")

    return errors, warnings

def validate_variables(dsl, metadata):
    """Validate that all variable names match project metadata."""
    valid_vars = [v['name'] for v in metadata.get('variables', [])]
    issues = []

    for script in dsl.get('scripts', []):
        for block in script.get('blocks', []):
            # Check fields
            for field_name, field_value in block.get('fields', {}).items():
                if field_name == 'VARIABLE' and field_value not in valid_vars:
                    issues.append(f"Invalid variable name '{field_value}' in script '{script.get('hatId')}'")
            # Check nested fields in inputs
            for input_name, input_value in block.get('inputs', {}).items():
                if isinstance(input_value, dict) and 'fields' in input_value:
                    for field_name, field_value in input_value.get('fields', {}).items():
                        if field_name == 'VARIABLE' and field_value not in valid_vars:
                            issues.append(f"Invalid variable name '{field_value}' in nested field of script '{script.get('hatId')}'")

    return issues

def validate_broadcasts(dsl, metadata):
    """Validate that all broadcast names match project metadata."""
    valid_broadcasts = metadata.get('broadcasts', [])
    issues = []

    for script in dsl.get('scripts', []):
        for block in script.get('blocks', []):
            if block.get('opcode') == 'event_broadcast':
                inputs = block.get('inputs', {})
                bcast_name = inputs.get('BROADCAST_INPUT', '')
                if bcast_name not in valid_broadcasts:
                    issues.append(f"Invalid broadcast name '{bcast_name}' in script '{script.get('hatId')}'")

    return issues

def validate_variable_values(dsl, metadata, game_balance):
    """Validate specific variable initialization values."""
    issues = []
    warnings = []

    # Initial lives
    has_lives_init = False
    for script in dsl.get('scripts', []):
        for block in script.get('blocks', []):
            if block.get('opcode') == 'data_setvariableto':
                if block.get('fields', {}).get('VARIABLE') == '生命':
                    if block.get('inputs', {}).get('VALUE') == 5:
                        has_lives_init = True
                    break

    if not has_lives_init:
        issues.append("Initial lives should be 5 per game_balance.yaml")

    # Initial time
    has_time_init = False
    for script in dsl.get('scripts', []):
        for block in script.get('blocks', []):
            if block.get('opcode') == 'data_setvariableto':
                if block.get('fields', {}).get('VARIABLE') == '时间':
                    if block.get('inputs', {}).get('VALUE') == 30:
                        has_time_init = True
                    break

    if not has_time_init:
        issues.append("Initial time should be 30 per game_balance.yaml")

    # Check for difficulty scaling
    has_scaling = False
    for script in dsl.get('scripts', []):
        for block in script.get('blocks', []):
            if block.get('opcode') == 'data_setvariableto':
                if block.get('fields', {}).get('VARIABLE') in ['apple_spawn_interval', 'enemy_spawn_interval']:
                    has_scaling = True
                    break

    if not has_scaling:
        warnings.append("No difficulty scaling for spawn intervals found")

    return issues, warnings

def validate_utf8_encoding(filepath):
    """Check if file is valid UTF-8."""
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            content = f.read()
            # Check for non-ASCII characters (Chinese, etc.)
            has_chinese = any(ord(c) > 127 for c in content)
            if not has_chinese:
                return False, "File contains no Chinese characters"
            return True, f"File is valid UTF-8 with Chinese characters"
    except Exception as e:
        return False, f"Failed to read as UTF-8: {e}"

